G1=$(group 'fwshift-addresses' 'FWShift: for the interfaces of 10.30.0.0-10.30.1.9 10.30.1.11-10.30.1.255 10.30.3.0-10.30.3.29 10.30.3.31-10.30.8.255 10.30.10.0-10.30.255.255') || exit 1
