# attach fwshift-shop-app: 10.30.2.20/31
G4=$(group 'fwshift-shop-app' 'FWShift: for the interfaces of 10.30.2.20/31') || exit 1
# attach fwshift-shop-db: 10.30.3.30
G5=$(group 'fwshift-shop-db' 'FWShift: for the interfaces of 10.30.3.30') || exit 1
# attach fwshift-shop-bastion: 10.30.9.5
